const d = msg.payload;

// SECURITY: Only allow valid server names
if (!/^server[1-5]$/.test(d.server_id)) {
    return null;
}

// Track state for ALL valid servers
const states = global.get('serverStates') || {};
states[d.server_id] = {
    load_score: d.load_score,
    cpu: d.cpu,
    ram: d.ram,
    network: d.network,
    timestamp: Date.now()
};
global.set('serverStates', states);

// Calculate global average for trend analysis
const loads = Object.values(states).map(s => s.load_score);
const avgLoad = loads.reduce((a, b) => a + b, 0) / loads.length;
global.set('avgLoad', avgLoad);
global.set('activeServers', loads.length);

// Exit if not in surcharge
if (d.load_score <= 80) {
  return null;
}

const now = Date.now();
const lastAction = global.get('lastAction') || {};

// 30s Cooldown per server
if ((now - (lastAction[d.server_id] || 0)) < 30000) {
  return null;
}

// Find Target (Available means < 70)
const others = Object.entries(states)
  .filter(([k, v]) => k !== d.server_id && v.load_score < 70)
  .sort((a, b) => a[1].load_score - b[1].load_score);

if (!others.length) {
  node.warn(`No healthy target found for migration from ${d.server_id}`);
  return null;
}

lastAction[d.server_id] = now;
global.set('lastAction', lastAction);

// Track alert count
const alertCount = (global.get('alertCount') || 0) + 1;
global.set('alertCount', alertCount);

msg.payload = {
  action: 'reduce_load',
  source: d.server_id,
  target: others[0][0],
  load_score: d.load_score,
  avg_load: avgLoad,
  alert_number: alertCount,
  timestamp: Math.floor(now / 1000)
};
return msg;

const d = msg.payload;
const line = `server_metrics,server_id=${d.server_id} cpu=${d.cpu},ram=${d.ram},network_mbps=${d.network},load_score=${d.load_score},temp=${d.temp},co2=${d.co2} ${d.timestamp}`;
msg.payload = line;
msg.headers = {
  "Authorization": "Token my-super-secret-auth-token",
  "Content-Type": "text/plain"
};
return msg;

const d = msg.payload;
const states = global.get('serverStates') || {};
const avgLoad = global.get('avgLoad') || 0;
const alertCount = global.get('alertCount') || 0;

// Build server status table
let statusTable = '';
Object.entries(states).sort().forEach(([id, data]) => {
    const emoji = data.load_score > 80 ? '🔴' : data.load_score > 60 ? '🟡' : '🟢';
    statusTable += `${emoji} ${id}: ${data.load_score.toFixed(1)}%\n`;
});

const telegramMsg = `🚨 *ALERTE #${alertCount} — LOAD BALANCER*\n\n` +
    `⚠️ Surcharge détectée sur *${d.source}*\n` +
    `📊 Charge: *${d.load_score.toFixed(1)}/100*\n` +
    `🔄 Migration → *${d.target}*\n\n` +
    `📡 *État du Cluster:*\n${statusTable}\n` +
    `📈 Charge Moyenne: *${avgLoad.toFixed(1)}%*\n\n` +
    `_IoT Auto-Scaling Engine v2.0_`;

msg.payload = {
    chat_id: "5851162500",
    text: telegramMsg,
    parse_mode: "Markdown"
};
msg.headers = {
  "Content-Type": "application/json"
};
return msg;

const body = msg.payload;
const validActions = ['reduce_load', 'restart', 'status'];
const validTargets = ['server1','server2','server3','server4','server5'];

if (body.action === 'status') {
    const states = global.get('serverStates') || {};
    const avgLoad = global.get('avgLoad') || 0;
    const alertCount = global.get('alertCount') || 0;
    msg.payload = {
        status: 'ok',
        servers: states,
        avg_load: avgLoad,
        total_alerts: alertCount,
        timestamp: new Date().toISOString()
    };
    msg.statusCode = 200;
    return [msg, null];
}

if (!validActions.includes(body.action)) {
    msg.payload = { error: 'Invalid action. Use: ' + validActions.join(', ') };
    msg.statusCode = 400;
    return [msg, null];
}
if (!validTargets.includes(body.target)) {
    msg.payload = { error: 'Invalid target. Use: ' + validTargets.join(', ') };
    msg.statusCode = 400;
    return [msg, null];
}

// Forward valid command to MQTT
const mqttMsg = {
    payload: JSON.stringify({
        action: body.action,
        target: body.target,
        source: 'command-center',
        timestamp: Math.floor(Date.now() / 1000)
    })
};

msg.payload = {
    status: 'ok',
    message: `Command '${body.action}' sent to ${body.target}`,
    timestamp: new Date().toISOString()
};
msg.statusCode = 200;

return [msg, mqttMsg];

const states = global.get('serverStates') || {};
const avgLoad = global.get('avgLoad') || 0;
const alertCount = global.get('alertCount') || 0;

const loads = Object.values(states).map(s => s.load_score);
const maxLoad = loads.length ? Math.max(...loads) : 0;
const minLoad = loads.length ? Math.min(...loads) : 0;

// Health score: 100 = perfect, 0 = all servers critical
const healthScore = Math.max(0, 100 - avgLoad);

// Time since last data per server
const now = Date.now();
const serverDetails = {};
Object.entries(states).forEach(([id, data]) => {
    serverDetails[id] = {
        ...data,
        status: data.load_score > 80 ? 'critical' : data.load_score > 60 ? 'warning' : 'healthy',
        age_seconds: Math.round((now - data.timestamp) / 1000)
    };
});

msg.payload = {
    system_health: Math.round(healthScore),
    active_servers: loads.length,
    avg_load: Math.round(avgLoad * 10) / 10,
    max_load: Math.round(maxLoad * 10) / 10,
    min_load: Math.round(minLoad * 10) / 10,
    total_alerts: alertCount,
    servers: serverDetails,
    timestamp: new Date().toISOString()
};
msg.statusCode = 200;
return msg;
